REQUIRED_HERMES_TRIGGER_SEMANTICS="hermes_desktop_contexts_immutable_delete|beforedeleteonhermes_desktop_contexts|raise(abort,'hermes_desktop_contexts_immutable');hermes_desktop_contexts_immutable_update|beforeupdateonhermes_desktop_contexts|raise(abort,'hermes_desktop_contexts_immutable');hermes_desktop_devices_binding_immutable|beforeupdateonhermes_desktop_devices|new.api_audience<>old.api_audience|new.connector_capabilities_json<>old.connector_capabilities_json|raise(abort,'hermes_desktop_device_binding_immutable');hermes_desktop_devices_revocation_monotonic|beforeupdateofrevoked_at,revoked_by_user_idonhermes_desktop_devices|old.revoked_atisnullandold.revoked_by_user_idisnull|new.revoked_atisnotnullandnew.revoked_by_user_idisnotnull|new.revoked_at>=old.paired_at|new.revoked_atisold.revoked_at|raise(abort,'hermes_desktop_device_revocation_not_monotonic');hermes_desktop_envelopes_binding_immutable|beforeupdateonhermes_desktop_envelopes|new.consent_basis<>old.consent_basis|new.expires_at<>old.expires_at|raise(abort,'hermes_desktop_envelope_binding_immutable');hermes_desktop_envelopes_state_transition|beforeupdateonhermes_desktop_envelopes|new.provider_request_json=old.provider_request_json|context.provider_request_json=new.provider_request_json|context.output_schema_sha256=new.output_schema_sha256|result.provider_request_sha256=old.provider_request_sha256|result.outcome='accepted'|result.recorded_at=new.submitted_at|new.submitted_at<old.expires_at|raise(abort,'hermes_desktop_envelope_state_transition_invalid');hermes_desktop_events_immutable_delete|beforedeleteonhermes_desktop_events|raise(abort,'hermes_desktop_events_immutable');hermes_desktop_events_immutable_update|beforeupdateonhermes_desktop_events|raise(abort,'hermes_desktop_events_immutable');hermes_desktop_pairings_binding_immutable|beforeupdateonhermes_desktop_pairings|new.api_audience<>old.api_audience|new.bound_issuer<>old.bound_issuer|new.bound_origin<>old.bound_origin|raise(abort,'hermes_desktop_pairing_binding_immutable');hermes_desktop_pairings_consumption_monotonic|beforeupdateofconsumed_at,consumed_device_idonhermes_desktop_pairings|old.consumed_atisnullandold.consumed_device_idisnull|new.consumed_atisnotnullandnew.consumed_device_idisnotnull|new.consumed_at<old.expires_at|new.consumed_atisold.consumed_at|raise(abort,'hermes_desktop_pairing_consumption_not_monotonic');hermes_desktop_results_append_only_delete|beforedeleteonhermes_desktop_results|raise(abort,'hermes_desktop_results_append_only');hermes_desktop_results_append_only_update|beforeupdateonhermes_desktop_results|raise(abort,'hermes_desktop_results_append_only')"
