  if [[ "$present" != "1" ]]; then
    echo "error: restored D1 export is missing required index: $index_name on $index_table" >&2
    exit 1
  fi
  printf '%s=%s\n' "$index_name" "$index_table" >> "$local_index_bindings"
done
IFS=',' read -r -a required_trigger_bindings < <(printf '%s\n' "$REQUIRED_TRIGGER_BINDINGS")
if (( ${#required_trigger_bindings[@]} != REQUIRED_TRIGGER_COUNT )); then
